create table if not exists treaty_ops_public_projections (id uuid primary key default gen_random_uuid(), source_type text not null, source_id uuid not null, source_version text not null, projection_purpose text not null, payload jsonb not null, freshness_at timestamptz not null, disputed boolean not null default false, suspended boolean not null default false, revoked boolean not null default false, published_at timestamptz, withdrawn_at timestamptz);
create table if not exists treaty_ops_audit_events (id uuid primary key default gen_random_uuid(), event_type text not null, actor_id uuid, actor_authority_id uuid, source_manifest_id uuid, policy_version text not null, schema_version text not null, jurisdiction text not null, idempotency_key text unique not null, payload jsonb not null, created_at timestamptz not null default now());
create table if not exists treaty_ops_outbox (id uuid primary key default gen_random_uuid(), topic text not null, aggregate_id uuid not null, payload jsonb not null, idempotency_key text unique not null, state text not null default 'pending', attempts integer not null default 0, available_at timestamptz not null default now(), created_at timestamptz not null default now());
